CREATE TABLE users (id UUID PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL CHECK (role IN ('STUDENT','FACULTY','ADMIN')), status VARCHAR(20) NOT NULL CHECK (status IN ('ACTIVE','INACTIVE','SUSPENDED')), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, last_login_at TIMESTAMPTZ);
CREATE TABLE assignments (id UUID PRIMARY KEY, title VARCHAR(160) NOT NULL, description TEXT NOT NULL, protocol VARCHAR(40) NOT NULL, difficulty VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL, requirements JSONB NOT NULL, concepts JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE assignment_attempts (id UUID PRIMARY KEY, student_id UUID NOT NULL REFERENCES users(id), assignment_id UUID NOT NULL REFERENCES assignments(id), status VARCHAR(20) NOT NULL, attempt_number INTEGER NOT NULL, execution_log TEXT, network_log TEXT, automated_score NUMERIC(5,2), started_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, ended_at TIMESTAMPTZ, UNIQUE(student_id, assignment_id, attempt_number));
CREATE TABLE submissions (id UUID PRIMARY KEY, student_id UUID NOT NULL REFERENCES users(id), assignment_id UUID NOT NULL REFERENCES assignments(id), attempt_id UUID NOT NULL REFERENCES assignment_attempts(id), solution TEXT, execution_output TEXT, network_log TEXT, automated_score NUMERIC(5,2), faculty_grade NUMERIC(5,2), faculty_feedback TEXT, status VARCHAR(20) NOT NULL, submitted_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, reviewed_at TIMESTAMPTZ);
CREATE INDEX attempts_student_assignment_idx ON assignment_attempts(student_id, assignment_id);
CREATE INDEX submissions_assignment_idx ON submissions(assignment_id);
